namespace Sunplus.Agent.UI._MemberInfo.ChangePassword
{
    using System.Web.UI;
    using Fanex.Agent.UI._MemberInfo.ChangePassword;
    using Fanex.Razorbill.Security.Configurations;
    using Sunplus.Agent.Model.Entities.Permission;

    public partial class ChangePassword_Page : Fanex.Age.UI.TplPage
    {
        public override void RenderContent(HtmlTextWriter writer)
        {
            this.RegisterJavascriptObject("alertInputOldPwd", Resources.Lang.alertInputOldPwd);
            this.RegisterJavascriptObject("alertPasswordEmpty", Resources.Lang.alertPasswordEmpty);
            this.RegisterJavascriptObject("alertErrorConfirm", Resources.Lang.alertErrorConfirm);
            this.RegisterJavascriptObject("alertPasswordRequire", Resources.Lang.lblPasswordRequire);
            this.RegisterJavascriptObject("alertPasswordSucc", Resources.Lang.lblPasswordChangedOK);
            this.RegisterJavascriptObject("alertWrongPasswordRule", Resources.Lang.lblPasswordWrongRule);
            this.RegisterJavascriptObject("pwdOldHint", Resources.Lang.lblPasswordDOldOne);
            this.RegisterJavascriptObject("pwdDAccountName", Resources.Lang.lblPasswordDAccountName);

            ChangePassword_Template tpl = new ChangePassword_Template();
            if (!CurrentUserSession.IsLogged)
            {
                this.RegisterJavascriptObject("firstLogged", true);
                this.RegisterJavascriptObject("forcechangepwd", Resources.Lang.forcechangepwd);
                // hide security code link
                tpl.SecurityCode = null;
            }

            if (CurrentUserSession.IsPasswordExpired)
            {
                this.RegisterJavascriptObject("pwdExpired", true);
                this.RegisterJavascriptObject("pwdExpiredMsg", Resources.Lang.lblPasswordExpired);
                this.RegisterJavascriptObject("pwdHint", Resources.Lang.lblPasswordHint);
                // hide security code link
                tpl.SecurityCode = null;
            }

            // If the SecurityCodeSection has Active property is TRUE, then we will use the NEW flow of Security Code.
            // Otherwise the OLD one will be used.
            if (!base.SecurityCodeSession.IsEnableSecurityCode && !UserPermission.IsShowSecurityVerify)
            {
                // hide security code link
                tpl.SecurityCode = null;
            }
            else
            {
                this.RegisterJavascriptObject("isNewSC", SecurityCodeConfig.IsActive);
            }

            // write template
            writer.Write(tpl);
        }

        public override void ProcessRequest(ref System.Collections.Hashtable p)
        {
        }

        public override object ValidateRequest(System.Collections.Hashtable p)
        {
            return null;
        }

        public override object InvokeData(System.Collections.Hashtable p)
        {
            return null;
        }
    }
}